def copy_replace(values, index, replacement):
    result = []
    i = 0
    while i < len(values):
        if i == index:
            result.append(replacement)
        else:
            result.append(values[i])
        i += 1
    return result

print(copy_replace([], -1, 9))
print(copy_replace([1, 2], 0, 8))
print(copy_replace([1, 2], -1, 8))

def positive_copy(values):
    result = []
    for value in values:
        if value > 0:
            result.append(value)
    return result

print(positive_copy([]))
print(positive_copy([3, 0, -1, 3]))
print(positive_copy([-2, 0]))
